"alzate-laterali-su-panca-inclinata":{"name":"Alzate laterali su panca inclinata","cat":"Petto e spalle","per":["terzino"],"eq":"Manubri","lvl":2,"mus":["Deltoidi"],"steps":["Sdraiati su un fianco su una panca inclinata con un manubrio.","Alza il braccio lateralmente fino all'altezza della spalla.","Scendi lento senza usare slancio."],"err":["Spalla che si solleva","Peso eccessivo"],"yt":"incline side lying lateral raise"},
