"alzate-frontali-con-disco":{"name":"Alzate frontali con disco","cat":"Petto e spalle","per":["terzino"],"eq":"Disco","lvl":1,"mus":["Deltoidi","Pettorali"],"steps":["Afferra un disco con entrambe le mani alle ore 9 e 3.","Alza il disco fino all'altezza degli occhi.","Scendi lento mantenendo il busto fermo."],"err":["Inarcare la schiena","Slancio con le gambe"],"yt":"plate front raise"},
