"dip-assistiti-con-elastico":{"name":"Dip assistiti con elastico","cat":"Petto e spalle","per":["terzino"],"eq":"Elastico","lvl":3,"mus":["Pettorali","Tricipiti"],"steps":["Fissa un elastico alle parallele e metti le ginocchia dentro.","Scendi controllato piegando i gomiti.","Spingi su aiutato dall'elastico."],"err":["Elastico che scivola","Spalle in avanti"],"yt":"banded dips"},
