"wrist-curl":{"name":"Wrist curl con manubri","cat":"Braccia","per":["terzino"],"eq":"Manubri","lvl":1,"mus":["Avambracci"],"steps":["Seduto con avambracci appoggiati sulle cosce, polsi fuori dal ginocchio.","Fletti i polsi verso l'alto.","Scendi lento senza muovere gli avambracci."],"err":["Alzare gli avambracci","Peso troppo alto"],"yt":"wrist curl"},
